namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

public static class RecipeData
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak rice noodles in warm water.\n2. Stir-fry shrimp until pink.\n3. Push aside, scramble eggs in pan.\n4. Add drained noodles, tamarind, and fish sauce.\n5. Toss with bean sprouts.\n6. Serve with crushed peanuts and lime.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheese, Sour cream, Salsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Red onion, Cilantro, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, and jalapeño.\n4. Add lime juice and cilantro.\n5. Season with salt.\n6. Serve immediately with chips.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until thick.\n3. Fold in chocolate mixture.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12-14 minutes.\n7. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken breast, Thai basil, Bamboo shoots, Fish sauce, Sugar", Steps = "1. Heat curry paste in a wok.\n2. Add half the coconut milk, stir until oil separates.\n3. Add sliced chicken, cook through.\n4. Pour in remaining coconut milk.\n5. Add bamboo shoots, fish sauce, and sugar.\n6. Finish with Thai basil leaves.", AverageRating = 4.4, RatingCount = 11 },
    };

    public static List<string> Categories => Recipes.Select(r => r.Category).Distinct().ToList();

    public static List<Recipe> GetByCategory(string category) =>
        Recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public static Recipe? GetById(int id) => Recipes.FirstOrDefault(r => r.Id == id);
}

