@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community - Home</PageTitle>

<h1>🍳 Recipe Sharing Community</h1>
<p class="lead">Discover and share delicious recipes from around the world!</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeData.Categories)
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeData.GetByCategory(category).Count recipes</p>
                    <a href="recipes/@category.ToLower()" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes"
@using RecipeCommunity.Models

<PageTitle>Browse Recipes</PageTitle>

<h1>Browse All Recipes</h1>

@foreach (var category in RecipeData.Categories)
{
    <h2 class="mt-4">@category</h2>
    <div class="row">
        @foreach (var recipe in RecipeData.GetByCategory(category))
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item"><a href="/recipes">Recipes</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <p class="card-text"><strong>Ingredients:</strong> @recipe.Ingredients</p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">Full Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeData.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (recipe is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes">Recipes</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Ingredients</h5>
                    <ul class="list-unstyled">
                        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructions</h5>
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate This Recipe</h4>
        <p class="text-muted">Current rating: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
        <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
    </div>
}
else
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/recipes" class="btn btn-primary">Browse All Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeData.GetById(Id);
    }
}

@using RecipeCommunity.Models
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 2rem;">
            @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "★" : "☆")
        </span>
    }

    @if (submitted)
    {
        <div class="alert alert-success mt-2" role="alert">
            Thanks! You rated this recipe @selectedRating star@(selectedRating != 1 ? "s" : "").
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int hoverRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        submitted = true;

        var recipe = RecipeData.GetById(RecipeId);
        if (recipe is not null)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
        }
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@submission.Title</strong>" with the community.</p>
        <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                <DataAnnotationsValidator />
                <ValidationSummary />

                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                        <option value="">-- Select a category --</option>
                        <option value="Italian">Italian</option>
                        <option value="Indian">Indian</option>
                        <option value="Thai">Thai</option>
                        <option value="Mexican">Mexican</option>
                        <option value="Desserts">Desserts</option>
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients" placeholder="List ingredients, one per line" />
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="7" @bind-Value="submission.Steps" placeholder="Describe the cooking steps..." />
                </div>

                <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid => !string.IsNullOrWhiteSpace(submission.Title)
                         && !string.IsNullOrWhiteSpace(submission.Category)
                         && !string.IsNullOrWhiteSpace(submission.Ingredients)
                         && !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var newRecipe = new Recipe
        {
            Id = RecipeData.Recipes.Count + 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        RecipeData.Recipes.Add(newRecipe);
        submitted = true;
    }

    private void Reset()
    {
        submission = new();
        submitted = false;
    }
}

