+              @onmouseout="() => hoverRating = 0"
+              style="cursor: pointer; font-size: 2rem;">
+            @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "★" : "☆")
+        </span>
+    }
+
+    @if (submitted)
+    {
+        <div class="alert alert-success mt-2" role="alert">
+            Thanks! You rated this recipe @selectedRating star@(selectedRating != 1 ? "s" : "").
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter]
+    public int RecipeId { get; set; }
+
+    private int selectedRating;
+    private int hoverRating;
+    private bool submitted;
+
+    private void Rate(int stars)
+    {
+        selectedRating = stars;
+        submitted = true;
+
+        var recipe = RecipeData.GetById(RecipeId);
+        if (recipe is not null)
+        {
+            var totalRating = recipe.AverageRating * recipe.RatingCount;
+            recipe.RatingCount++;
+            recipe.AverageRating = (totalRating + stars) / recipe.RatingCount;
+        }
+    }
+}
+

